// TypeScript Version: 4.1

import dgelq2 = require( './index' );

// TESTS //

// The function returns a number...
{
	var A = new Float64Array( 12 );
	var TAU = new Float64Array( 3 );
	var WORK = new Float64Array( 3 );

	dgelq2( 'column-major', 3, 4, A, 3, TAU, WORK ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	var A = new Float64Array( 12 );
	var TAU = new Float64Array( 3 );
	var WORK = new Float64Array( 3 );

	dgelq2( 5, 3, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( true, 3, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( false, 3, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( null, 3, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( undefined, 3, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( [], 3, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( {}, 3, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( ( x: number ): number => x, 3, 4, A, 3, TAU, WORK ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	var A = new Float64Array( 12 );
	var TAU = new Float64Array( 3 );
	var WORK = new Float64Array( 3 );

	dgelq2( 'column-major', '5', 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( 'column-major', true, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( 'column-major', false, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( 'column-major', null, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( 'column-major', undefined, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( 'column-major', [], 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( 'column-major', {}, 4, A, 3, TAU, WORK ); // $ExpectError
	dgelq2( 'column-major', ( x: number ): number => x, 4, A, 3, TAU, WORK ); // $ExpectError
}

