// The compiler throws an error if the function is provided unsupported number of arguments...
{
	var A = new Float64Array( 12 );
	var TAU = new Float64Array( 3 );
	var WORK = new Float64Array( 3 );

	dgelq2(); // $ExpectError
	dgelq2( 'column-major' ); // $ExpectError
	dgelq2( 'column-major', 3 ); // $ExpectError
	dgelq2( 'column-major', 3, 4 ); // $ExpectError
	dgelq2( 'column-major', 3, 4, A ); // $ExpectError
	dgelq2( 'column-major', 3, 4, A, 3 ); // $ExpectError
	dgelq2( 'column-major', 3, 4, A, 3, TAU ); // $ExpectError
	dgelq2( 'column-major', 3, 4, A, 3, TAU, WORK, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	var A = new Float64Array( 12 );
	var TAU = new Float64Array( 3 );
	var WORK = new Float64Array( 3 );

	dgelq2.ndarray( 3, 4, A, 1, 3, 0, TAU, 1, 0, WORK, 1, 0 ); // $ExpectType number
}

