	dgelq2.ndarray( 3, 4, A ); // $ExpectError
	dgelq2.ndarray( 3, 4, A, 1 ); // $ExpectError
	dgelq2.ndarray( 3, 4, A, 1, 3 ); // $ExpectError
	dgelq2.ndarray( 3, 4, A, 1, 3, 0 ); // $ExpectError
	dgelq2.ndarray( 3, 4, A, 1, 3, 0, TAU ); // $ExpectError
